// План specs/job-payments.md 3.2 (кейс .qa/tests/job-payments/JP-11). Pre-Prod, preprod-ttp, десктоп Chrome, EN.
// #5bfdd1 (контроль): запрет правки касается только Stripe-платежей — ручной Cash открывается в «Edit Payment»
// с открытыми полями и кнопками Delete / Cancel / Save.
// @writes @data: работа «QA-AUTO pay cash … #67b4b4» ($5) + ручной платёж Cash $5.00. Денег нет.
// Очистка в finally: работа → Cancelled (платёж остаётся в отменённой работе).
import { test, expect } from '../../fixtures';
import {
  REMAINING, blockMessaging, cancelJob, createJobWithBalance, historyRow, methodButton, openPaymentsTab, openTakeAPayment,
} from './payments-helpers';

test.describe('Job → Payments: manual payment stays editable (#5bfdd1)', () => {
  test('QA-AUTO: manual Cash payment opens Edit Payment with editable fields and Delete / Cancel / Save #5bfdd1 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(180_000);
    const page = await asUser('preprod-ttp');
    const messaging = await blockMessaging(page);
    let jobUrl: string | null = null;
    try {
      jobUrl = await createJobWithBalance(page, 'cash');
      await openPaymentsTab(page, jobUrl);

      // Шаг 1: Take a payment → Cash → Add Payment (Cash, $5) → сохранить
      const choose = await openTakeAPayment(page);
      await methodButton(choose, 'Cash').click();
      const form = page.getByRole('dialog').filter({ hasText: /Add Payment/ });
      await expect(form).toBeVisible();
      await form.getByRole('button', { name: /^(Save|Add Payment|Save Payment)$/ }).last().click();
      await expect(form).toBeHidden();

      const cashRow = historyRow(page, /^\s*Cash/).filter({ hasNotText: /Ref: pi_/ });
      await expect(cashRow).toHaveCount(1);
      await expect(cashRow).toContainText(REMAINING);
      await expect(cashRow).toContainText('Completed');

      // Шаг 2: клик по строке → «Edit Payment», поля открыты, Delete / Cancel / Save (контроль к «מה רצוי» #5bfdd1)
      await cashRow.click();
      const dialog = page.getByRole('dialog').filter({ hasText: 'Edit Payment' });
      await expect(dialog).toBeVisible();
      await expect(dialog.getByText(/went through Stripe/)).toHaveCount(0);
      await expect(dialog.getByRole('combobox').filter({ hasText: 'Cash' }).first()).toBeEnabled();
      await expect(dialog.getByLabel(/Amount/).or(dialog.getByRole('spinbutton')).first()).toBeEditable();
      await expect(dialog.getByLabel('Notes').or(dialog.getByRole('textbox').last()).first()).toBeEditable();
      await expect(dialog.getByRole('button', { name: /Delete/ })).toBeVisible();
      await expect(dialog.getByRole('button', { name: /^Cancel$/ })).toBeVisible();
      await expect(dialog.getByRole('button', { name: /^Save$/ })).toBeVisible();

      // Cancel без изменений
      await dialog.getByRole('button', { name: /^Cancel$/ }).click();
      await expect(dialog).toBeHidden();
      await expect(cashRow).toContainText(REMAINING);

      expect(messaging, 'запросов отправки SMS/email быть не должно').toEqual([]);
    } finally {
      await cancelJob(page, jobUrl);
    }
  });
});
